from pathlib import Path
import sys

app_path=Path(sys.argv[1] if len(sys.argv)>1 else 'budget-checker/src/app.js')
css_path=Path(sys.argv[2] if len(sys.argv)>2 else 'budget-checker/styles.css')
app=app_path.read_text(encoding='utf-8')
css=css_path.read_text(encoding='utf-8')

def replace_function(src,name,new_text):
    token='function '+name+'('
    start=src.find(token)
    if start<0:
        raise SystemExit('missing function '+name)
    brace=src.find('{',start)
    depth=0
    quote=None
    escape=False
    i=brace
    while i<len(src):
        ch=src[i]
        if quote:
            if escape:
                escape=False
            elif ch=='\\':
                escape=True
            elif ch==quote:
                quote=None
        else:
            if ch in ("'",'"','`'):
                quote=ch
            elif ch=='{':
                depth+=1
            elif ch=='}':
                depth-=1
                if depth==0:
                    return src[:start]+new_text+src[i+1:]
        i+=1
    raise SystemExit('unterminated function '+name)

helpers=r"""function mpRoundedRubles(kopecks){return Math.round(Number(kopecks||0)/100);}
function mpSameAfterRubleRounding(a,b){return mpRoundedRubles(a)===mpRoundedRubles(b);}
function mpRoundingMessage(label,control,external){const raw=Number(external||0)-Number(control||0),left=mpRoundedRubles(control).toLocaleString('ru-RU'),right=mpRoundedRubles(external).toLocaleString('ru-RU');return `${label}: исходная разница ${raw>=0?'+':''}${money(raw)} обусловлена округлением. После округления до целых рублей значения совпадают (${left} ₽ = ${right} ₽).`;}"""
anchor='function mpCompare('
idx=app.find(anchor)
if idx<0: raise SystemExit('mpCompare anchor missing')
if 'function mpRoundedRubles(' not in app:
    app=app[:idx]+helpers+'\n'+app[idx:]

new_compare=r"""function mpCompare(ctx,external,fileName,extracted){const rows=[],channelSummary=[],ext=mpAggregateExternal(extracted,ctx),technicalCosts=mpTechnicalCostGroups(extracted);let controlTotal=0,mediaTotal=0,grossControlTotal=0,grossMediaTotal=0,matchedControlTotal=0,matchedMediaTotal=0;for(const c of ctx.channels){const e=ext.matched.get(mpNorm(c.channel)),externalMonths=e?e.months:Array(12).fill(0),path=[ctx.division,ctx.brand,c.typeMedia,c.channel].filter(Boolean),ct=c.months.reduce((a,b)=>a+b,0),et=externalMonths.reduce((a,b)=>a+b,0),exclusion=mpFindExclusion(ctx.brand,'channel',c.channel);grossControlTotal+=ct;grossMediaTotal+=et;if(!exclusion){controlTotal+=ct;mediaTotal+=et;matchedControlTotal+=ct;matchedMediaTotal+=et;for(let m=0;m<12;m++){const cv=c.months[m]||0,ev=externalMonths[m]||0;if(cv===ev)continue;if(mpSameAfterRubleRounding(cv,ev)){rows.push({type:'ROUNDING_NOTE',roundingOnly:true,path,month:m,control:cv,external:ev,difference:0,rawDifference:ev-cv,message:mpRoundingMessage(C.MONTHS[m],cv,ev),sources:e?.sources?.[m]||[]});continue;}rows.push({type:'MONTH_MISMATCH',path,month:m,control:cv,external:ev,difference:ev-cv,message:`${C.MONTHS[m]}: бюджет канала «${c.channel}» в медиаплане отличается от актуального флоучарта.`,sources:e?.sources?.[m]||[]});}if(ct!==et){if(mpSameAfterRubleRounding(ct,et)){rows.push({type:'ROUNDING_NOTE',roundingOnly:true,path,month:null,control:ct,external:et,difference:0,rawDifference:et-ct,message:mpRoundingMessage(`Итог по каналу «${c.channel}»`,ct,et),sources:e?[...new Set(e.sources.flat())]:[]});}else{const missing=!e&&ct!==0;rows.push({type:missing?(mpIsAuxName(c.channel)?'MISSING_AUX_COST':'MISSING_CHANNEL'):'CHANNEL_TOTAL_MISMATCH',path,month:null,control:ct,external:et,difference:et-ct,message:missing?(mpIsAuxName(c.channel)?`В медиаплане не найден кост «${c.channel}», предусмотренный актуальным флоучартом.`:`Канал «${c.channel}» есть в актуальном флоучарте, но его бюджет не найден в медиаплане.`):`Итог по каналу «${c.channel}» отличается от актуального флоучарта.`,sources:e?[...new Set(e.sources.flat())]:[]});}}}channelSummary.push({kind:'channel',channel:c.channel,typeMedia:c.typeMedia,control:ct,external:et,difference:mpSameAfterRubleRounding(ct,et)?0:et-ct,rawDifference:et-ct,roundingOnly:ct!==et&&mpSameAfterRubleRounding(ct,et),excluded:!!exclusion,exclusion});}
for(const u of ext.unmapped.values()){const total=u.months.reduce((a,b)=>a+b,0),exclusion=mpFindExclusion(ctx.brand,'external',u.raw);grossMediaTotal+=total;if(!exclusion){mediaTotal+=total;for(let m=0;m<12;m++)if(u.months[m])rows.push({type:u.auxiliary?'UNMAPPED_AUX_COST':'UNMAPPED_CHANNEL',path:[ctx.division,ctx.brand,u.raw].filter(Boolean),month:m,control:0,external:u.months[m],difference:u.months[m],message:u.auxiliary?`В медиаплане найден дополнительный кост «${u.raw}», но в флоучарте не найден однозначный канал для его сверки.`:`Секция медиаплана «${u.raw}» не сопоставилась ни с одним каналом флоучарта.`,sources:u.sources[m]||[]});}channelSummary.push({kind:'external',channel:u.raw,typeMedia:'Не сопоставлено',control:0,external:total,difference:total,rawDifference:total,excluded:!!exclusion,exclusion});}
const technicalTotal=technicalCosts.reduce((a,x)=>a+x.amount,0);grossMediaTotal+=technicalTotal;mediaTotal+=technicalTotal;for(const t of technicalCosts)channelSummary.push({kind:'technical',channel:t.label,typeMedia:'Технические расходы',control:0,external:t.amount,difference:t.amount,rawDifference:t.amount,technical:true,sources:t.sources});
const tnsTotal=technicalCosts.filter(x=>x.kind==='tns').reduce((a,x)=>a+x.amount,0),channelGap=matchedControlTotal-matchedMediaTotal,tnsExplains=tnsTotal>0&&Math.abs(channelGap-tnsTotal)<=100;if(tnsExplains){for(const d of rows){if(!d.roundingOnly&&(d.type==='MONTH_MISMATCH'||d.type==='CHANNEL_TOTAL_MISMATCH')&&d.difference<0){d.explainedByTechnical=true;d.technicalLabel='Счётчик TNS';d.message+=` Общий разрыв по сопоставленным каналам объясняется отдельным техкостом «Счётчик TNS» (${money(tnsTotal)}), который в медиаплане вынесен отдельной строкой.`;}}}
const rawDifference=mediaTotal-controlTotal,overallRoundingOnly=rawDifference!==0&&mpSameAfterRubleRounding(controlTotal,mediaTotal),difference=overallRoundingOnly?0:rawDifference,excludedCount=channelSummary.filter(x=>x.excluded).length,roundingNoteCount=rows.filter(x=>x.roundingOnly).length,criticalMismatchCount=rows.filter(x=>!x.explainedByTechnical&&!x.roundingOnly).length,explainedMismatchCount=rows.filter(x=>x.explainedByTechnical).length;return{fileName,brand:ctx.brand,division:ctx.division,rows,channelSummary,controlTotal,mediaTotal,difference,rawDifference,overallRoundingOnly,grossControlTotal,grossMediaTotal,excludedCount,technicalCosts,technicalTotal,technicalExplanation:tnsExplains?{kind:'tns',label:'Счётчик TNS',amount:tnsTotal,channelGap}:null,criticalMismatchCount,explainedMismatchCount,roundingNoteCount,extracted};}"""
app=replace_function(app,'mpCompare',new_compare)

new_type=r"""function mpTypeLabel(v){return({ROUNDING_NOTE:'Совпадает после округления',MONTH_MISMATCH:'Расхождение по месяцу',CHANNEL_TOTAL_MISMATCH:'Расхождение по итогу канала',MISSING_CHANNEL:'Канал не найден в медиаплане',MISSING_AUX_COST:'Не учтён дополнительный кост',UNMAPPED_CHANNEL:'Не сопоставлен канал медиаплана',UNMAPPED_AUX_COST:'Не сопоставлен дополнительный кост',TECHNICAL_COST:'Технический расход медиаплана'})[v]||v;}"""
app=replace_function(app,'mpTypeLabel',new_type)

new_render=r"""function mpRenderComparison(result){state.lastMediaPlanComparison=result;const src=result.extracted.detectedSheets||[],unparsed=result.extracted.issues||[],summary=result.channelSummary.filter(x=>x.control||x.external||x.excluded),excluded=result.channelSummary.filter(x=>x.excluded),critical=result.rows.filter(x=>!x.explainedByTechnical&&!x.roundingOnly),explained=result.rows.filter(x=>x.explainedByTechnical),rounding=result.rows.filter(x=>x.roundingOnly);const notes=[];if(explained.length)notes.push(`${explained.length} строк детализации объясняются техническим костом медиаплана`);if(rounding.length)notes.push(`${rounding.length} строк отличаются только исходными копейками и совпадают после математического округления до целых рублей`);const statusHtml=critical.length?info(`Требуют проверки: ${critical.length}. Ниже показано, где именно расходятся месяцы, каналы и итоговые суммы.`,'error'):notes.length?info(`Критических расхождений нет. ${notes.join('. ')}.`):info('По сравниваемым каналам медиаплан совпадает с актуальным бюджетом.');const techHtml=tech.length? `<div class="mp-tech-note"><div><b>Технические расходы медиаплана:</b> ${tech.map(x=>`${esc(x.label)} — ${money(x.amount)}`).join(' · ')}</div>${result.technicalExplanation?`<div>Сумма «${esc(result.technicalExplanation.label)}» объясняет общий разрыв между суммой сопоставленных каналов и флоучартом. Техкост учтён в общем итоге медиаплана, но не выделен отдельным каналом во флоучарте.</div>`:''}${result.overallRoundingOnly?`<div>Итоговая исходная разница ${result.rawDifference>=0?'+':''}${money(result.rawDifference)} обусловлена округлением; после округления до целых рублей итоги совпадают.</div>`:''}</div>`:'';document.getElementById('mpResult').innerHTML=`<div class="mp-auto-meta">Автоматически определено: <b>${esc(result.brand)}</b> · ${esc(result.division||'дивизион не указан')} · таблицы размещений: ${src.map(esc).join(', ')||'—'}</div><div class="grid cols-3" style="margin-top:14px"><div><div class="muted">Флоучарт в сверке</div><div class="metric">${money(result.controlTotal)}</div></div><div><div class="muted">Медиаплан в сверке</div><div class="metric">${money(result.mediaTotal)}</div></div><div><div class="muted">Расхождение</div><div class="metric ${result.difference?'diff-neg':'diff-pos'}">${result.difference>=0?'+':''}${money(result.difference)}</div></div></div>${excluded.length?`<div class="help mp-exclusion-summary">Исключено из расчёта: ${excluded.length}. Исключённые строки остаются видимыми, но не влияют на итоговое расхождение.</div>`:''}${techHtml}${statusHtml}<div class="actions" style="margin-top:12px"><button id="mpExportAuto" class="btn">Выгрузить сверку в Excel</button>${excluded.length?`<button id="mpExclusions" class="btn ghost">Исключения · ${excluded.length}</button>`:''}<button id="mpManual" class="btn ghost">Ручное сопоставление</button></div><h3 style="margin-top:18px">Сверка по каналам</h3><div class="table-wrap"><table class="mp-channel-table"><thead><tr><th>Тип медиа</th><th>Канал</th><th>Флоучарт</th><th>Медиаплан</th><th>Расхождение</th></tr></thead><tbody>${summary.map(x=>`<tr class="${x.excluded?'mp-excluded-row ':''}${x.technical?'mp-technical-row':''}${x.roundingOnly?'mp-rounding-row':''}"><td>${esc(x.typeMedia||'')}</td><td>${x.technical?`<div class="mp-channel-cell"><div><span>${esc(x.channel)}</span><div class="mp-technical-note">Отдельный техкост медиаплана</div></div></div>`:`<div class="mp-channel-cell"><div><span>${esc(x.channel)}</span>${x.excluded?`<div class="mp-excluded-note">Исключено · ${esc(mpExclusionReasonLabel(x.exclusion?.reasonCode))}${x.exclusion?.comment?` · ${esc(x.exclusion.comment)}`:''}</div>`:x.roundingOnly?`<div class="mp-rounding-note">Совпадает после округления до целых рублей · исходная разница ${x.rawDifference>=0?'+':''}${money(x.rawDifference)}</div>`:''}</div><button type="button" class="mp-row-menu" title="Действия" aria-label="Действия для канала" data-mp-exclude-kind="${esc(x.kind||'channel')}" data-mp-exclude-channel="${esc(x.channel)}">⋯</button></div>`}</td><td class="money">${money(x.control)}</td><td class="money">${money(x.external)}</td><td class="money ${x.excluded?'':(x.technical?'mp-tech-value':(x.roundingOnly?'mp-rounding-value':(x.difference?'diff-neg':'diff-pos')))}">${x.excluded?'<span class="mp-excluded-pill">Исключено</span>':x.roundingOnly?'0 ₽':`${x.difference>=0?'+':''}${money(x.difference)}`}</td></tr>`).join('')||'<tr><td colspan="5">Нет бюджетных строк</td></tr>'}</tbody><tfoot><tr class="mp-channel-total"><td></td><td>Итого в сверке</td><td class="money">${money(result.controlTotal)}</td><td class="money">${money(result.mediaTotal)}</td><td class="money ${result.difference?'diff-neg':'diff-pos'}">${result.difference>=0?'+':''}${money(result.difference)}</td></tr></tfoot></table></div><h3 style="margin-top:18px">Что не сходится</h3><div class="table-wrap"><table class="mp-diff-table"><thead><tr><th>Тип</th><th>Путь</th><th>Месяц</th><th>Флоучарт</th><th>Медиаплан</th><th>Расхождение</th><th>Комментарий</th><th>Источник</th></tr></thead><tbody>${result.rows.map(d=>`<tr class="${d.roundingOnly?'mp-rounding-row':(d.explainedByTechnical?'mp-tech-explained-row':'')}"><td>${esc(d.roundingOnly?'Совпадает после округления':(d.explainedByTechnical?'Объяснено техкостом':mpTypeLabel(d.type)))}</td><td class="mp-diff-path">${esc((d.path||[]).join(' → '))}</td><td>${d.month==null?'Итого':esc(C.MONTHS[d.month])}</td><td class="money">${money(d.control||0)}</td><td class="money">${money(d.external||0)}</td><td class="money ${d.roundingOnly?'mp-rounding-value':(d.explainedByTechnical?'mp-tech-value':(d.difference?'diff-neg':'diff-pos'))}">${d.roundingOnly?'0 ₽':`${d.difference>=0?'+':''}${money(d.difference||0)}`}</td><td><div class="mp-diff-comment" title="${esc(d.message||'')}">${esc(d.message||'')}</div></td><td>${mpSourceDetailsHtml(d.sources)}</td></tr>`).join('')||'<tr><td colspan="8">Расхождений нет</td></tr>'}</tbody></table></div>${unparsed.length?`<div class="help" style="margin-top:10px">Не использованы при сверке: ${unparsed.length} строк/таблиц, которые парсер не смог однозначно классифицировать. Их можно проверить через ручное сопоставление.</div>`:''}`;document.getElementById('mpExportAuto').onclick=()=>mpExportComparison(result);document.getElementById('mpManual').onclick=()=>mpShowManual(state.reconcile.data);const exclusionsBtn=document.getElementById('mpExclusions');if(exclusionsBtn)exclusionsBtn.onclick=()=>mpOpenExclusionsList(result);document.querySelectorAll('[data-mp-exclude-channel]').forEach(btn=>btn.onclick=()=>mpOpenExclusionModal(result,btn.dataset.mpExcludeKind||'channel',btn.dataset.mpExcludeChannel));}"""
app=replace_function(app,'mpRenderComparison',new_render)

new_export=r"""function mpExportComparison(r){const wb=XLSX.utils.book_new(),excluded=r.channelSummary.filter(x=>x.excluded),summary=[['Сверка медиаплана с актуальным бюджетом',''],['Файл',r.fileName],['Бренд',r.brand],['Дивизион',r.division],['Флоучарт в сверке, ₽',r.controlTotal/100],['Медиаплан в сверке, ₽',r.mediaTotal/100],['Расхождение после округления, ₽',r.difference/100],['Исходная разница, ₽',(r.rawDifference??r.difference)/100],['Технические расходы медиаплана, ₽',(r.technicalTotal||0)/100],['Исключено каналов',excluded.length],['Требуют проверки',r.criticalMismatchCount??r.rows.length],['Объяснено техкостами',r.explainedMismatchCount||0],['Совпадает после округления',r.roundingNoteCount||0]],channels=[['Тип строки','Тип медиа','Канал','Флоучарт, ₽','Медиаплан, ₽','Расхождение, ₽','Исходная разница, ₽','Статус','Причина исключения','Комментарий'],...r.channelSummary.map(x=>[x.technical?'Технический расход':'Канал',x.typeMedia,x.channel,x.control/100,x.external/100,(x.roundingOnly?0:x.difference)/100,(x.rawDifference??x.difference)/100,x.technical?'Техкост медиаплана':(x.excluded?'Исключено':(x.roundingOnly?'Совпадает после округления':'В сверке')),x.excluded?mpExclusionReasonLabel(x.exclusion?.reasonCode):'',x.exclusion?.comment||'']),['Итого','','Итого в сверке',r.controlTotal/100,r.mediaTotal/100,r.difference/100,(r.rawDifference??r.difference)/100,r.overallRoundingOnly?'Совпадает после округления':'','','']],details=[['Статус','Тип','Путь','Месяц','Флоучарт, ₽','Медиаплан, ₽','Расхождение, ₽','Исходная разница, ₽','Комментарий','Источник'],...r.rows.map(d=>[d.roundingOnly?'Совпадает после округления':(d.explainedByTechnical?'Объяснено техкостом':'Требует проверки'),mpTypeLabel(d.type),(d.path||[]).join(' → '),d.month==null?'Итого':C.MONTHS[d.month],(d.control||0)/100,(d.external||0)/100,(d.roundingOnly?0:(d.difference||0))/100,(d.rawDifference??d.difference??0)/100,d.message||'',(d.sources||[]).join('; ')])];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(summary),'Итоги');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(channels),'По каналам');XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(details),'Расхождения');if((r.technicalCosts||[]).length){const tech=[['Тип','Наименование','Сумма, ₽','Источник'],...r.technicalCosts.map(x=>[x.kind,x.label,x.amount/100,(x.sources||[]).join('; ')])];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(tech),'Технические расходы');}if(excluded.length){const ex=[['Тип медиа','Канал','Флоучарт, ₽','Медиаплан, ₽','Причина','Комментарий'],...excluded.map(x=>[x.typeMedia,x.channel,x.control/100,x.external/100,mpExclusionReasonLabel(x.exclusion?.reasonCode),x.exclusion?.comment||''])];XLSX.utils.book_append_sheet(wb,XLSX.utils.aoa_to_sheet(ex),'Исключения');}XLSX.writeFile(wb,`Сверка_медиаплана_${budgetSafeFilePart(r.brand)}_${budgetToday()}.xlsx`,{compression:true});}"""
app=replace_function(app,'mpExportComparison',new_export)

